Method.Source:
/// <summary>
/// Calculate batch job execution duration in seconds
/// </summary>
/// <returns>Duration in seconds between start and end time</returns>
[SysClientCacheDataMethod(true)]
public static display Seconds durationSeconds(BatchHistory _this)
{
    Seconds duration;

    if (_this.StartDateTime && _this.EndDateTime)
    {
        duration = int642int(DateTimeUtil::getDifference(_this.EndDateTime, _this.StartDateTime));
    }

    return duration;
}
